/**
 * Get authentic live wire articles for a state and publisher
 */
export function getLiveArticlesForState(stateId: string, preferredSource?: string): WireArticle[] {
  const list = LIVE_WIRE_ARTICLES_BY_STATE[stateId] || [];
  if (!preferredSource) return list;
  
  const clean = preferredSource.toLowerCase();
  const matched = list.filter(a => a.source?.name?.toLowerCase().includes(clean));
  if (matched.length > 0) return matched;
  return list;
}
